private void assignUserToOrganization(Connection con, String newUserUuid, String organizationId, String departmentId)  {
    String sqlAssignUserToOrganization = "INSERT INTO dir_employment (id, userId, organizationId, departmentId) " +
                                         "VALUES (?, ?, ?, ?);";
    try  {
        PreparedStatement stmt = con.prepareStatement(sqlAssignUserToOrganization);
        String employmentId = UuidGenerator.getInstance().getUuid();  // Generate a unique employment ID
        stmt.setString(1, employmentId);
        stmt.setString(2, newUserUuid);
        stmt.setString(3, organizationId);
        stmt.setString(4, departmentId);
        
        int rowsAffected = stmt.executeUpdate();
        LogUtil.info("User Assignment to Organization", "Rows Affected: " + rowsAffected);
